function bindFinalReleaseArtifacts(draft, files, context, hash) {
  const copy = value => JSON.parse(JSON.stringify(value));
  const equal = (a,b,label) => { if (JSON.stringify(a)!==JSON.stringify(b)) throw Error(label); };
  const need = (ok,label) => { if (!ok) throw Error(label); };
  const own = (o,k) => Object.prototype.hasOwnProperty.call(o,k);
  const at = (value, pointer) => {
    if (pointer==="") return value;
    need(typeof pointer==="string" && pointer.startsWith("/"), "invalid pointer");
    return pointer.slice(1).split("/").reduce((o,k) => {
      k=k.replace(/~1/g,"/").replace(/~0/g,"~");
      need(o!==null && typeof o==="object" && own(o,k), "missing pointer "+pointer);
      return o[k];
    }, value);
  };
  const bytes = s => unescape(encodeURIComponent(s)).length;
  const r=copy(draft), required=r.artifactBindings.files.map(x=>x.path);
  need(required.length===136 && new Set(required).size===136,"exact catalog slots");
  const file = path => {
    const f=files[path]; need(f && f.path===path,"file "+path);
    need(/^[a-f0-9]{64}$/.test(f.sha256) && Number.isSafeInteger(f.bytes) && f.bytes>=0, "file envelope "+path);
    need((typeof f.retainedBlob==="string" && /^[a-f0-9]{40}$/.test(f.retainedBlob)) || f.receiptOrEnvelopeRef, "immutable envelope "+path);
    if (own(f,"content")) {
      need(typeof f.content==="string" && hash(f.content)===f.sha256 && bytes(f.content)===f.bytes,"raw bytes "+path);
      if (own(f,"value")) equal(JSON.parse(f.content), f.value, "parsed raw "+path);
    }
    return f;
  };
  const envelope = path => {
    const f=file(path);
    return {path,sha256:f.sha256,bytes:f.bytes,retainedBlob:f.retainedBlob??null,
      receiptOrEnvelopeRef:copy(f.receiptOrEnvelopeRef??null)};
  };
  const value = (path,pointer="") => {
    const f=file(path); need(own(f,"value"),"authentic JSON required "+path);
    return at(f.value,pointer);
  };
  const selector = s => {
    const v=value(s.file,s.jsonPointer), serialized=JSON.stringify(v);
    need(serialized!==undefined,"undefined selector");
    const e={file:s.file,jsonPointer:s.jsonPointer,verified:true,
      fileEnvelope:envelope(s.file),jsonValueSha256:hash(serialized),
