function prepareFinalActiveDocuments({docs,correspondence,obligations,release,releaseRef,attempt,updatedAtUtc,mainAtLastVerified,assignments,sha256,correspondenceOnly=false}) {
  const copy=v=>JSON.parse(JSON.stringify(v));
  const same=(a,b,n)=>{if(JSON.stringify(a)!==JSON.stringify(b))throw Error(n);};
  const need=(b,n)=>{if(!b)throw Error(n);};
  const h=v=>sha256(JSON.stringify(v));
  const old=Object.fromEntries(["correspondence","obligations","proposal","attempts"].map(k=>{
    need(sha256(docs[k].content)===docs[k].sha256,"document bytes "+k);return [k,JSON.parse(docs[k].content)];
  }));
  need(release.qualification.strictSh1Qualified===true && release.qualification.correspondenceRowsDischarged===33 && release.qualification.stageObligationsDischarged===27,"completed release");
  need(correspondence.rows.length===33 && correspondence.rows.every(r=>r.strictSh1Discharged===true && r.generalPreservationProven===false),"completed33");
  if(!correspondenceOnly) need(obligations && obligations.rows.length===27 && obligations.rows.every(r=>r.strictDischarged===true),"completed27");
  need(attempt.attempt===17 && attempt.sourceRef===release.source.sourceRef && attempt.runId===release.execution.expectedRunId && attempt.status==="success","actual completed attempt17");
  need(attempt.orchestrationHeadSha===release.execution.expectedHeadSha && release.execution.requiredSourceRef===release.source.sourceRef,"distinct actual orchestration and compiler source identities");
  need(release.execution.priorExecution.expectedRunId===38015134511 && release.execution.priorExecution.compilerConclusion==="cancelled" && release.execution.priorExecution.providerConclusion==="skipped","preserved cancelled predecessor");
  need(old.attempts.attempts.length===16 && h(old.attempts.attempts)==="557a694fb4e41826e9b11a6ca69b7e8131aec91090436ff8262fa0b70552c8a2","preserved16 attempts");
  need(release.execution.generationExecution.expectedRunId===38021634599 && release.execution.generationExecution.compilerConclusion==="failure" && release.execution.generationExecution.providerConclusion==="skipped","preserved completed-generation failed producer");
  need(release.execution.expectedRunId===38027413274 && release.execution.expectedWorkflowId===380282667 && release.execution.expectedHeadSha==="719f5ec4225baf51d1969cc3b5e4cbc6959fad4a" && release.execution.compilerJobId===114141103218 && release.execution.compilerConclusion==="success" && release.execution.providerConclusion==="success","actual evidence-completion execution");
  same(release.execution.evidenceProducer.currentExecution,{runId:release.execution.expectedRunId,workflowId:release.execution.expectedWorkflowId,runAttempt:release.execution.runAttempt,compilerJobId:release.execution.compilerJobId,headSha:release.execution.expectedHeadSha},"current evidence-producer identity");
  need(release.execution.evidenceProducer.sourceRef===release.execution.expectedHeadSha && release.execution.evidenceCompletionInputs.inputsFile.sha256 && release.execution.evidenceCompletionInputs.evidenceInventoryFile.sha256 && release.execution.evidenceCompletionInputs.completionFile.sha256,"actual completion provenance bound");
  const out={correspondence:copy(correspondence),obligations:obligations==null?null:copy(obligations),proposal:copy(old.proposal),attempts:copy(old.attempts)};
  const qualifiedSourceRef=release.source.sourceRef, rpin=copy(releaseRef);
  const scope={
    qualifiedEntry:"psCompilerSh1TypeScriptSources",qualifiedLane:release.activation.qualifiedLane,
    selectedByPsconfig:false,selectedSeed:"R",sourceAuthority:".lean",
    sourceGrammar:"ps-0.9-r3/new-only/bounded-selfhost-subset",typescript:"7.0.2",
    generalPreservationProven:false,formalPreservationProven:false,
    producedReceiptsUnchanged:true,releaseRecordReference:rpin
  };
  const providerScope={
    sourceRef:release.provider.expectedSourceRef,compilerSourceRef:qualifiedSourceRef,
    labeledInputs:8,uniqueStreams:release.provider.uniqueStreamCount,
    exactC2C3StreamsOnly:true,N1ProviderChecked:false,allExamplesProviderChecked:false,
    receipt:copy(release.execution.providerFile),emissionWasGatedByThisCheck:false
  };
  const latest={
    attempt:17,sourceRef:qualifiedSourceRef,runId:release.execution.expectedRunId,
    workflowId:release.execution.expectedWorkflowId,runAttempt:release.execution.runAttempt,
    orchestrationHeadSha:release.execution.expectedHeadSha,compiledSourceRef:release.execution.requiredSourceRef,
    priorExecution:copy(release.execution.priorExecution),
    continuationInputs:copy(release.execution.continuationInputs),
    continuationInputsRole:release.execution.continuationInputsRole,
    generationExecution:copy(release.execution.generationExecution),
    evidenceProducer:copy(release.execution.evidenceProducer),
    evidenceProducerRepair:copy(release.execution.evidenceProducerRepair),
    evidenceCompletionInputs:copy(release.execution.evidenceCompletionInputs),
    currentOutputOwnership:copy(release.execution.currentOutputOwnership),
    generationOwnership:copy(release.execution.generationOwnership),
    status:"success",compilerJobId:release.execution.compilerJobId,providerJobId:release.execution.providerJobId,
    sourceClosureSha256:release.source.sourceClosureSha256,sourceInputsSha256:release.source.sourceInputsSha256,
    recipeSha256:release.recipe.sha256,
    generations:release.generations.map(g=>({name:g.name,status:g.status,compilerSha256:g.actualCompilerSha256,
      executingCompilerSha256:g.actualExecutingCompilerSha256,typescriptSha256:g.actualTypeScriptSha256,
      receipt:copy(g.receipt),fullCompilerIrBoundary:g.fullCompilerIrBoundary})),
    fixedPoint:"C2/C3-complete-compared-artifact-tuple-equal",
    nativeParity:"N1/C2/C3-TypeScript-and-JavaScript-equal",
    compilerQualification:copy(release.execution.qualificationFile),
    strictEvidenceBinder:copy(release.execution.strictBinderFile),
    providerReceipt:copy(release.execution.providerFile),providerScope,
    strictSh1Qualified:true,semanticContractQualified:true,providerChecked:true,
    strictQualificationScope:scope,releaseRecordReference:rpin,
    completedAtUtc:release.execution.completedAtUtc
  };
  const historical=(doc,key)=>({path:docs[doc].path,blob:docs[doc].blob,sha256:docs[doc].sha256,bytes:docs[doc].bytes,jsonPointer:"/"+key});
  const currentRequest={
    status:"completed-and-qualified-for-declared-strict-entry-and-lane",
    sourceRef:qualifiedSourceRef,runId:release.execution.expectedRunId,runAttempt:release.execution.runAttempt,
    compilerJobId:release.execution.compilerJobId,providerJobId:release.execution.providerJobId,
    sourceClosureSha256:release.source.sourceClosureSha256,recipeSha256:release.recipe.sha256,
    recipeFileCount:48,workflowBlob:release.execution.workflowSourceBlob,
    orchestrationHeadSha:release.execution.expectedHeadSha,compiledSourceRef:release.execution.requiredSourceRef,
    executionMode:"authenticated-retained-generations-with-separate-corrected-evidence-producer",
    generationOwnership:copy(release.execution.generationOwnership),
    evidenceProducer:copy(release.execution.evidenceProducer),
    evidenceCompletionInputs:copy(release.execution.evidenceCompletionInputs),
    rebuiltGenerationsByEvidenceCompletion:[],
    allRequiredPhasesCompleted:true,releaseRecordReference:rpin,
    strictSh1Qualified:true,semanticContractQualified:true,providerChecked:true,providerScope
  };
  const finalDisposition={
    status:"qualified-for-explicit-strict-entry-and-current-lane; all33 correspondence and27 stage dispositions bound to release-qualification.json",
