    const k=parts.at(-1);need(Object.prototype.hasOwnProperty.call(o,k),"assignment field");
    same(o[k],expected,"assignment guard "+pointer);o[k]=copy(value);
  };
  if(!correspondenceOnly) for(const a of assignments)setAt(out[a.document],a.pointer,a.current,a.valueAfterCompleteDisposition);
