  p.activation.selectedSeed="R";p.activation.selectedSeedChanged=false;
  need(typeof p.stages[6].status==="string" && p.stages[6].status.endsWith("; complete-strict-contract-pending"),"historical M6 status tail");
  p.stages[6].status=p.stages[6].status.slice(0,-"; complete-strict-contract-pending".length)+"; declared-strict-PSC0-SH/1-qualified-for-explicit-entry-and-current-lane";
  p.stages[6].currentStrictReleaseRecordReference=copy(rpin);
  out.attempts.attempts.push(copy(attempt));
  same(out.attempts.attempts.slice(0,16),old.attempts.attempts,"all16 historical attempt objects unchanged");
  out.attempts.strictSh1Qualified=true;out.attempts.semanticContractQualified=true;
  out.attempts.updatedAtUtc=updatedAtUtc;out.attempts.mainAtLastVerified=mainAtLastVerified;
  out.attempts.previousQualificationRequestReference=historical("attempts","nextQualification");
  out.attempts.nextQualification={status:"none-required-for-this-qualified-source-checkpoint",qualifiedSourceRef,releaseRecordReference:copy(rpin),
