  out.attempts.currentStrictReleaseRecordReference=copy(rpin);
  same(out.correspondence.rows,correspondence.rows,"summary leaves completed33 unchanged");
  same(out.obligations.rows,obligations.rows,"summary leaves completed27 unchanged");
  need(out.proposal.activation.selectedByPsconfig===false && out.proposal.activation.enforcementInstalled===true,"scoped activation summary");
  return {documents:out,latestExecution:latest,scope,providerScope,releaseRef:copy(rpin)};
}

